package net.civeira.phylax.feature.observe.observeddashboard.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboard;
import net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject.BuiltinVO;

@RequiredArgsConstructor
public class BuiltinValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<BuiltinVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param builtin
   * @return
   */
  public T builtin(BuiltinVO builtin) {
    this.value = Optional.of(builtin);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param builtin
   * @return
   */
  public T builtin(Optional<BuiltinVO> builtin) {
    this.value = builtin;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param builtin
   * @return
   */
  public T builtin(Boolean builtin) {
    this.value = Optional.of(BuiltinVO.from(builtin));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Boolean> getBuiltin() {
    return value.map(BuiltinVO::isBuiltin);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<BuiltinVO> getBuiltinValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public BuiltinVO readBuiltin(final Optional<ObservedDashboard> original,
      final ConstraintFailList fails) {
    BuiltinVO result = value.orElse(original.map(ObservedDashboard::getBuiltinValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "builtin", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetBuiltin() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetBuiltinIfMatches(final String field) {
    if ("builtin".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
